  { id:"scr125", t:"screen", d:8, k:"tf", v:true, en:{q:"In Warner Bros.' Vitaphone system, the sound came from separate discs, not from the film strip."}, tr:{q:"Warner Bros.'un Vitaphone sisteminde ses, film şeridinden değil ayrı plaklardan geliyordu."} },
  { id:"scr126", t:"screen", d:8, k:"tf", v:false, en:{q:"The sitcom \"I Love Lucy\" was shot with a single camera on 35 mm film before a live studio audience."}, tr:{q:"\"I Love Lucy\" dizisi, canlı stüdyo seyircisi önünde 35 mm filme tek kamerayla çekiliyordu."} }
